CREATE OR REPLACE VIEW `view_messages_users` AS select cast(((`agg`.`owner_id` * 4294967296) + `agg`.`peer_id`) as unsigned) AS `id`,`agg`.`company_id` AS `company_id`,`agg`.`owner_id` AS `mu_owner_user_manager_id`,`agg`.`peer_id` AS `mu_peer_user_manager_id`,`agg`.`messages_count` AS `mu_messages_count`,`agg`.`unread_count` AS `mu_unread_count`,`lm`.`id` AS `mu_last_message_id`,`lm`.`content` AS `mu_last_content`,`lm`.`status` AS `mu_last_status`,`lm`.`sender_user_manager_id` AS `mu_last_sender_user_manager_id`,coalesce(`lm`.`sent_at`,`lm`.`created_at`) AS `mu_last_message_at`,`om`.`id` AS `om_id`,`om`.`username` AS `om_username`,`oc`.`name` AS `oc_name`,`pm`.`id` AS `pm_id`,`pm`.`username` AS `pm_username`,`pm`.`status` AS `pm_status`,`pc`.`uuid` AS `pc_uuid`,`pc`.`name` AS `pc_name`,`pc`.`email` AS `pc_email`,`agg`.`first_at` AS `created_at`,coalesce(`lm`.`sent_at`,`lm`.`created_at`) AS `updated_at`,NULL AS `deleted_at` from ((((((select `p`.`owner_id` AS `owner_id`,`p`.`peer_id` AS `peer_id`,max(`p`.`message_id`) AS `last_id`,count(0) AS `messages_count`,sum(((`p`.`received` = 1) and (`p`.`read_at` is null))) AS `unread_count`,min(`p`.`created_at`) AS `first_at`,`p`.`company_id` AS `company_id` from (select `codeigniter54900_db`.`messages_manager`.`sender_user_manager_id` AS `owner_id`,`codeigniter54900_db`.`messages_manager`.`recipient_user_manager_id` AS `peer_id`,`codeigniter54900_db`.`messages_manager`.`id` AS `message_id`,`codeigniter54900_db`.`messages_manager`.`created_at` AS `created_at`,`codeigniter54900_db`.`messages_manager`.`read_at` AS `read_at`,0 AS `received`,`codeigniter54900_db`.`messages_manager`.`company_id` AS `company_id` from `codeigniter54900_db`.`messages_manager` where ((`codeigniter54900_db`.`messages_manager`.`deleted_at` is null) and (`codeigniter54900_db`.`messages_manager`.`recipient_user_manager_id` is not null) and (`codeigniter54900_db`.`messages_manager`.`status` in ('scheduled','sent'))) union all select `codeigniter54900_db`.`messages_manager`.`recipient_user_manager_id` AS `recipient_user_manager_id`,`codeigniter54900_db`.`messages_manager`.`sender_user_manager_id` AS `sender_user_manager_id`,`codeigniter54900_db`.`messages_manager`.`id` AS `id`,`codeigniter54900_db`.`messages_manager`.`created_at` AS `created_at`,`codeigniter54900_db`.`messages_manager`.`read_at` AS `read_at`,1 AS `1`,`codeigniter54900_db`.`messages_manager`.`company_id` AS `company_id` from `codeigniter54900_db`.`messages_manager` where ((`codeigniter54900_db`.`messages_manager`.`deleted_at` is null) and (`codeigniter54900_db`.`messages_manager`.`recipient_user_manager_id` is not null) and (`codeigniter54900_db`.`messages_manager`.`status` = 'sent'))) `p` group by `p`.`owner_id`,`p`.`peer_id`,`p`.`company_id`) `agg` join `codeigniter54900_db`.`messages_manager` `lm` on((`lm`.`id` = `agg`.`last_id`))) left join `codeigniter54900_db`.`user_manager` `om` on(((`om`.`id` = `agg`.`owner_id`) and (`om`.`deleted_at` is null)))) left join `codeigniter54900_db`.`user_profiles` `oc` on(((`oc`.`user_manager_id` = `om`.`id`) and (`oc`.`deleted_at` is null)))) left join `codeigniter54900_db`.`user_manager` `pm` on(((`pm`.`id` = `agg`.`peer_id`) and (`pm`.`deleted_at` is null)))) left join `codeigniter54900_db`.`user_profiles` `pc` on(((`pc`.`user_manager_id` = `pm`.`id`) and (`pc`.`deleted_at` is null))));
CREATE OR REPLACE VIEW `view_message_users_groups` AS select `um`.`id` AS `id`,`cmx`.`company_id` AS `company_id`,`um`.`username` AS `um_username`,`um`.`status` AS `um_status`,`uc`.`name` AS `uc_name`,`uc`.`email` AS `uc_email`,(select count(0) from (`codeigniter54900_db`.`message_group_members` `m` join `codeigniter54900_db`.`message_groups_manager` `g` on(((`g`.`id` = `m`.`message_groups_manager_id`) and (`g`.`deleted_at` is null)))) where ((`m`.`user_manager_id` = `um`.`id`) and (`m`.`status` = 'active') and (`m`.`deleted_at` is null) and (`g`.`company_id` = `cmx`.`company_id`))) AS `groups_count`,(select left(group_concat(`g`.`name` order by `g`.`name` ASC separator ', '),500) from (`codeigniter54900_db`.`message_group_members` `m` join `codeigniter54900_db`.`message_groups_manager` `g` on(((`g`.`id` = `m`.`message_groups_manager_id`) and (`g`.`deleted_at` is null)))) where ((`m`.`user_manager_id` = `um`.`id`) and (`m`.`status` = 'active') and (`m`.`deleted_at` is null) and (`g`.`company_id` = `cmx`.`company_id`))) AS `groups_names`,`um`.`created_at` AS `created_at`,`um`.`updated_at` AS `updated_at`,`um`.`deleted_at` AS `deleted_at` from ((`codeigniter54900_db`.`user_manager` `um` join `codeigniter54900_db`.`company_members` `cmx` on(((`cmx`.`user_manager_id` = `um`.`id`) and (`cmx`.`status` = 'active') and (`cmx`.`deleted_at` is null)))) left join `codeigniter54900_db`.`user_profiles` `uc` on(((`uc`.`user_manager_id` = `um`.`id`) and (`uc`.`deleted_at` is null))));
